import {formatValue,renderOverview,renderChart,renderProfiles} from './result-visuals.js';
import {inclusiveEnd,exclusiveEnd,resultRows} from './workflow.js';
const $=s=>document.querySelector(s);
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={view:'assistant',workspace:null,tables:[],source:null,messages:[],analysis:null,confirmed:null,result:null,editMetric:null,metricSearch:'',metricStatus:'all',fieldRole:'all'};
const names={assistant:'智能取数',metrics:'指标字典',fields:'数据字段字典',history:'已保存的分析',settings:'连接与模型'};
const aggs={sum:'求和',count:'记录数',count_distinct:'去重计数',avg:'平均值',min:'最小值',max:'最大值',ratio:'数值合计 ÷ 去重数量',ratio_of_sums:'分子合计 ÷ 分母合计'};
const roleLabels={scope:'范围条件',time:'业务时间',measure:'数值度量',derived:'派生比率',snapshot:'时点数值',technical:'技术字段'};
const grains={total:'合计',day:'按天',week:'按周',month:'按月'};
const opNames={eq:'等于',ne:'不等于',gt:'大于',gte:'大于等于',lt:'小于',lte:'小于等于',not_null:'有值',is_null:'为空',in:'属于以下值'};
const options=(items,selected)=>items.map(([v,l])=>`<option value="${h(v)}" ${v===selected?'selected':''}>${h(l)}</option>`).join('');
const THEME_KEY='marketing-theme';
function resolveTheme(){const saved=localStorage.getItem(THEME_KEY);if(saved==='light'||saved==='dark')return saved;return matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';}
function applyTheme(theme){document.documentElement.setAttribute('data-theme',theme);const b=$('#theme-toggle');if(b){const dark=theme==='dark';b.setAttribute('aria-pressed',String(dark));const label=dark?'切换到浅色模式':'切换到深色模式';b.setAttribute('aria-label',label);b.title=label;}}
function toggleTheme(){const next=document.documentElement.getAttribute('data-theme')==='dark'?'light':'dark';localStorage.setItem(THEME_KEY,next);applyTheme(next);}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500);}
async function api(url,body,method){const response=await fetch(url,{method:method||(body?'POST':'GET'),headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw new Error(data.error||'请求失败');return data;}
async function busy(button,fn){if(button?.disabled)return;const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<span class="spinner"></span>处理中…';}try{return await fn();}catch(e){toast(e.message);const error=$('#form-error');if(error)error.textContent=e.message;}finally{if(button?.isConnected){button.disabled=false;button.innerHTML=old;}}}
async function refresh(){state.workspace=await api('/api/workspace');$('#metric-count').textContent=state.workspace.metrics.length;}
async function checkHealth(){try{const data=await api('/api/health');state.health=data;$('#connection').textContent=`${data.database.connected?'● 数据库已连接':'○ 数据库未连接'} · ${data.model.configured?'模型已配置':'模型未配置'}`;}catch{$('#connection').textContent='服务连接失败';}}
function header(title,desc,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function empty(title,desc){return `<div class="empty"><h3>${title}</h3><p>${desc}</p></div>`;}
function label(text,control,note=''){return `<label><span>${text}</span>${control}${note?`<small>${note}</small>`:''}</label>`;}
function fieldOptions(source,selected,kind='',blank=false){const cols=(source?.columns||[]).filter(c=>kind==='time'?c.role==='time':kind==='number'?c.role==='measure':kind==='scope'?c.role==='scope':kind==='filter'?['scope','time'].includes(c.role):true);return (selected&&!cols.some(c=>c.name===selected)?`<option value="${h(selected)}" selected>不可用字段：${h(selected)}（请重新选择）</option>`:'')+options([...(blank?[['',kind==='number'?'请选择数值':'不分组 / 不使用']]:[]),...cols.map(c=>[c.name,`${c.businessLabel||c.label||c.name}${c.unit?'（'+c.unit+'）':''}${c.meaningStatus==='confirmed'?' · 已确认':''} · ${c.name}`])],selected);}
function fieldName(source,name){return source?.columns.find(c=>c.name===name)?.businessLabel||source?.columns.find(c=>c.name===name)?.label||name;}
function scopeRows(container){return [...container.querySelectorAll('.filter-row')].map(r=>{const operator=r.querySelector('.filter-operator').value;const raw=r.querySelector('.filter-value').value;return {field:r.querySelector('.filter-field').value,operator,value:operator==='in'?selectedFilterValues(r.querySelector('.filter-value')):raw};});}
function semanticIntro(){return `<div class="semantic-banner"><div><span class="eyebrow">仅连接数据库</span><h2>先定范围，再算数值。</h2><p>账户、计划和日期决定统计对象；消耗、曝光和点击才参与计算。</p></div><div class="semantic-example"><span class="scope-token">哪些数据：AD · 所选日期 · 指定账户</span><span class="measure-token">计算什么：总点击 ÷ 总曝光 × 100</span><span class="derived-token">怎么看：按计划对比点击率</span></div></div>`;}

function navigate(view){captureDraft();state.view=view;history.replaceState(null,'','?view='+view);document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===view));$('#page-title').textContent=names[view];render();}
function render(){({assistant:renderAssistant,metrics:renderMetrics,fields:renderFields,history:renderHistory,settings:renderSettings}[state.view])();}
function renderAssistant(){
 if(!state.analysis&&!state.messages.length){$('#content').innerHTML=`<section class="hero"><div class="eyebrow">业务问题 → 范围条件 → 数值口径</div><h1>哪些投放数据？<br><em>要算哪个数据指标？</em></h1><p>只使用数据库。先确认平台、日期、账户和计划范围，再计算消耗、曝光、点击率与 ROI。</p><form class="prompt-box" id="ask-form"><textarea id="question" aria-label="业务问题" placeholder="例如：看最近7个完整日的AD投放消耗，按账户对比" required minlength="2"></textarea><div class="prompt-bottom"><span>可直接用自然语言提问，也可从指标字典选择</span><button class="btn primary" type="submit">分析业务问题 <span>↗</span></button></div></form><div class="examples"><button type="button" data-nav="metrics">不想写问题？直接选择指标 →</button><button data-example="统计最近7个完整日的AD投放消耗，按广告账户看">AD账户消耗对比 ↗</button><button data-example="统计最近7个完整日的AD点击率，按计划看">按计划看点击率 ↗</button><button data-example="查看最近7个完整日的ADQ净成交ROI，按部门看">ADQ部门净成交ROI ↗</button></div></section><div class="overview"><div class="stat"><strong>${state.workspace.metrics.filter(m=>m.status==='active').length}</strong><span>已启用数据指标</span></div><div class="stat"><strong>${state.workspace.metrics.filter(m=>m.status==='draft').length}</strong><span>待完善的口径</span></div><div class="stat"><strong>${state.workspace.queries.length}</strong><span>已保存 SQL</span></div></div><div class="guide"><div><b>01 / 说出业务问题</b>仅检索数据库的真实表与字段。</div><div><b>02 / 确认统计口径</b>分清范围、数值与分组，确认后计算。</div><div><b>03 / 保存并取数</b>保留定义版本和 SQL，随时复用。</div></div>`;return;}
 const a=state.analysis,m=state.workspace.metrics.find(x=>x.id===a?.metricId);
 $('#content').innerHTML=header('把这次业务口径确认清楚','左侧核对含义与真实值，右侧选择日期、范围和展示方式。','<button class="btn" data-action="reset">新建问数</button>')+`<div class="steps"><b>01 理解问题</b><span>${a?'→ 02 确认口径':'模型分析中'}</span><span>→ 03 查看结果</span></div><div class="split"><div><section class="panel"><div class="panel-title"><h2>业务对话</h2><span class="pill">数据库 · AI</span></div>${state.messages.map(msg=>`<div class="message ${msg.role}">${h(msg.role==='assistant'?msg.summary:msg.content)}</div>`).join('')}${state.busy?'<div class="busy-note"><span class="spinner"></span>正在匹配指标与真实字段，含校验自动重试，最长约 2 分钟…</div>':''}${a?.questions.map((q,i)=>`<div class="question"><p>${h(q.question)}</p><div class="actions">${q.options.map((o,j)=>`<button class="btn small" data-answer="${i}:${j}">${h(o)}</button>`).join('')}</div></div>`).join('')||''}<form id="followup-form" class="answer-input"><input id="followup" placeholder="补充时间、范围或你想采用的口径…" aria-label="补充业务条件" required minlength="2"><button class="btn primary" ${state.busy?'disabled':''}>补充说明</button></form>${state.analysisError?`<div class="callout error">${h(state.analysisError)}<br>本次没有生成默认答案，请检查连接后重试。</div>`:''}</section>${a?`<section class="panel" id="metric-review">${metricReview(m)}</section>`:''}${a&&!m?`<div class="panel"><h3>字典中还没有适用的指标</h3><p>可以基于真实数据表补充定义，保存后重新分析这个问题。</p><button class="btn primary" data-action="suggest-metric">${a.suggestedMetric?'检查并保存建议指标':'配置一个新指标'}</button></div>`:''}</div><div>${a?`<section class="panel query-ready"><div class="panel-title"><h2>业务确认单</h2><span class="pill ${m?.status!=='active'?'draft':''}">${m?.status==='active'?'待你确认':'需完善指标'}</span></div><form id="confirm-form"><div class="form-grid"><div class="full">${label('采用指标',`<select id="q-metric" required>${options([['','请选择指标'],...state.workspace.metrics.map(m=>[m.id,m.name+(m.status==='draft'?'（草稿）':'')])],a.metricId)}</select>`)}</div><div class="full scope-section-title">① 统计范围 · 哪些数据</div><div class="full actions"><button type="button" class="btn small" data-preset="yesterday">昨天</button><button type="button" class="btn small" data-preset="week">最近7个完整日</button><button type="button" class="btn small" data-preset="month">本月至今</button></div>${label('开始日期',`<input type="date" id="q-start" value="${h(a.startDate)}" required>`)}${label('结束日期（包含当天）',`<input type="date" id="q-end" value="${h(inclusiveEnd(a.endDate))}" required>`)}<div class="full">${label('统计归属时间',`<select id="q-time">${fieldOptions(state.workspace.sources.find(s=>s.id===m?.source),a.timeField||m?.timeField,'time')}</select>`)}</div><div class="full scope-section-title">② 展示方式 · 按什么看</div>${label('统计粒度',`<select id="q-grain">${options(Object.entries(grains),a.grain)}</select>`)}${label('分组方式',`<select id="q-dimension">${fieldOptions(state.workspace.sources.find(s=>s.id===m?.source),a.dimension||'','scope',true)}</select>`)}<div class="full scope-box"><div class="panel-title"><h3>额外范围条件</h3><button class="btn small" type="button" data-action="add-query-scope">＋ 添加</button></div><p class="small-text">例如只统计某个账户；更改分组不会改变筛选范围。</p><div id="query-scope">${(a.scopeFilters||[]).map(f=>filterRow(f,state.workspace.sources.find(s=>s.id===m?.source))).join('')}</div></div></div>${a.questions.length?'<div class="callout warning">助手提出了待澄清问题。请在左侧补充说明，或在确认单中明确选择你认可的指标、日期和范围。</div>':''}<div id="form-error" class="inline-error"></div><button class="btn" style="width:100%;margin-top:20px" ${state.busy?'disabled':''}>保存这次分析</button><button class="btn primary" type="submit" data-execute="true" style="width:100%;margin-top:8px">确认并查看结果</button><p class="small-text" style="margin:12px 0 0">保存后可随时复用；也可以立即查看统计结果。</p></form></section>`:'<div class="panel">分析完成后，这里会展示可修改的业务确认单。</div>'}</div></div>${state.confirmed?queryPanel(state.confirmed):''}`;
}
function metricReview(m){
 if(!m)return '<div class="callout warning">请先选择数据指标；范围和数值会随所选指标展示。</div>';
 const source=state.workspace.sources.find(s=>s.id===m.source),name=n=>fieldName(source,n);
 const base=m.aggregation==='ratio_of_sums'?`${name(m.valueField)}合计 ÷ ${name(m.denominatorField)}合计`:m.aggregation==='ratio'?`${name(m.valueField)}合计 ÷ 不同${m.distinctFields.map(name).join(' + ')}的数量`:m.aggregation==='count'?'记录条数':m.aggregation==='count_distinct'?`不同${m.distinctFields.map(name).join(' + ')}的数量`:`${aggs[m.aggregation]}（${name(m.valueField)}）`;
 const formula=base+(!m.aggregation.startsWith('count')?`${Number(m.scale)!==1?' ÷ '+m.scale:''}${Number(m.multiplier||1)!==1?' × '+m.multiplier:''}`:'');
 return `<div class="evidence-entry"><strong>先看看这个指标用的真实数据</strong><p>核对日期、账户、计算数值和单位，避免同名字段选错。</p><button type="button" class="btn" data-preview-metric="${m.id}">查看对应原始数据</button><div class="small-text">${[m.timeField,m.valueField,m.denominatorField].filter(Boolean).map(n=>`${h(name(n))}：${source?.columns.find(c=>c.name===n)?.meaningStatus==='confirmed'?'已确认':'含义待核对'}`).join(' · ')}</div></div><div class="measure-review"><span class="role-tag measure">计算数值</span><h3>${h(formula)}</h3><p>${h(m.description)}</p><span class="small-text">输出单位：${h(m.unit||'数量')}</span></div><div class="scope-review"><span class="role-tag scope">固定范围</span><p>${m.filters.map(f=>h(`${name(f.field)} ${opNames[f.operator]} ${Array.isArray(f.value)?f.value.join('、'):f.value||''}`)).join('<br>')||'未限制账户或计划，可在下方添加范围条件。'}</p></div><details class="definition-detail"><summary>数据依据与注意事项</summary><p class="table-name">${h(m.source)}</p><p class="small-text">${h(m.notes)}</p>${m.snapshotPolicy==='latest_per_day'?'<p class="small-text">先取每天各业务实体的最新快照，再汇总。</p>':''}</details>`;
}
function queryPanel(q){return `<section class="panel" id="saved-query"><div class="panel-title"><div><span class="pill">已保存 · 指标 v${q.metric.revision}</span><h2 style="margin-top:12px">${h(q.name)} · 已确认口径</h2></div><div class="actions"><button class="btn small" data-reuse="${q.id}">调整条件后复用</button><button class="btn small" data-rename-query="${q.id}">重命名</button><button class="btn small danger" data-delete-query="${q.id}">删除记录</button><button class="btn small" data-copy="${q.id}">复制 SQL</button><button class="btn small" data-download="${q.id}">下载 .sql</button></div></div><p>${h(q.summary)}</p><details class="sql-detail"><summary>查看计算依据与 SQL（可选）</summary><pre class="code">${h(q.displaySql)}</pre></details><div class="actions"><button class="btn primary" data-run="${q.id}" data-mode="full" ${state.runningQuery?'disabled':''}>执行确认范围</button><button class="btn" data-run="${q.id}" data-mode="sample" ${state.runningQuery?'disabled':''}>仅试跑开始日</button></div><p class="small-text" style="margin:12px 0">只读执行，上限 12 秒；超过 500 组会明确提示截断。试跑只查询开始日，不改变已保存的完整日期范围。</p><div id="query-result">${state.runningQuery===q.id?'<div class="busy-note">正在查询，结果返回后将在这里显示…</div>':state.result?.id===q.id?resultPanel(state.result):''}</div></section>`;}
function resultPanel(r){
 const keys=r.rows.length?Object.keys(r.rows[0]):[],rows=resultRows(r.rows,{search:state.resultSearch||'',sort:state.resultSort||'original'});
 const pageCount=Math.max(1,Math.ceil(rows.length/20)),pageIndex=Math.min(state.resultPage||0,pageCount-1),pageRows=rows.slice(pageIndex*20,pageIndex*20+20);
 const nullText=['ratio','ratio_of_sums'].includes(r.aggregation)?'无法计算（分母为0或缺少数值）':'未记录数值';
 const choices=[['original','原始顺序'],['value:desc','指标值：从高到低'],['value:asc','指标值：从低到高'],...(keys.includes('period')?[['period:asc','日期：从早到晚'],['period:desc','日期：从晚到早']]:[]),...(keys.includes('dimension')?[['dimension:asc','分组名称：排序']]:[])];
 return `<div class="callout ${r.mode==='sample'?'warning':''}"><strong>${r.mode==='sample'?'开始日试跑结果，不代表完整周期':'按确认范围查询'}</strong><br>实际范围：${h(r.start)} 至 ${h(inclusiveEnd(r.end))}（包含起止日） · 返回 ${r.rows.length} 组 · ${r.elapsed} ms${r.executedAt?' · 查询于 '+h(r.executedAt):''}${r.matchedRows!==null&&r.matchedRows!==undefined?`<br>${r.truncated?'已展示分组对应':'匹配'} ${h(r.matchedRows)} 条记录`:''}${r.truncated?'<br><strong>结果超过500组，目前只展示前500组。搜索、排序和导出均只针对这500组，可缩小范围后重查。</strong>':''}</div>${r.rows.length?`${renderOverview(rows,{unit:r.unit,aggregation:r.aggregation,exact:state.exactValues,partial:r.truncated||rows.length!==r.rows.length})}<div class="visual-controls"><label class="check-inline"><input type="checkbox" id="exact-values" ${state.exactValues?'checked':''}>显示原始精度</label><label class="check-inline"><input type="checkbox" id="show-chart" ${state.hideChart?'':'checked'}>显示图表</label><button type="button" class="btn small" data-action="copy-result-summary">复制结果摘要</button><span class="small-text">概览与明细覆盖筛选结果；趋势图可单独选择分组</span></div>${state.hideChart?'':renderChart(rows,r.rows,{series:state.chartSeries||'',unit:r.unit,grain:state.workspace.queries.find(q=>q.id===r.id)?.definition.grain})}<div class="result-toolbar"><input id="result-search" aria-label="搜索查询结果" placeholder="查找账户、日期或结果值" value="${h(state.resultSearch||'')}"><select id="result-sort" aria-label="结果排序">${options(choices,state.resultSort||'original')}</select><span>匹配 ${rows.length} / ${r.rows.length} 组</span></div><div class="table-wrap result-table"><table><thead><tr>${keys.map(k=>`<th>${h({period:'统计日期',dimension:'分组',value:`指标值（${r.unit||'数值'}）`}[k]||k)}</th>`).join('')}<th>核对数据</th></tr></thead><tbody>${pageRows.map(row=>`<tr>${keys.map(k=>`<td ${k==='value'?'data-result-value':''} title="${h(row[k]??nullText)}">${h(row[k]===null?(k==='value'?nullText:'未填写分组'):k==='value'?formatValue(row[k],{exact:state.exactValues}):row[k])}</td>`).join('')}<td><button type="button" class="btn small" data-result-row="${r.rows.indexOf(row)}">看原始记录</button></td></tr>`).join('')}</tbody></table>${rows.length?'':empty('没有匹配的结果','更换搜索词，或清空搜索查看本次返回的所有分组。')}</div><div class="result-pages"><span>第 ${pageIndex+1} / ${pageCount} 页 · 每页20组</span><button type="button" class="btn small" data-result-page="${pageIndex-1}" ${pageIndex===0?'disabled':''}>上一页</button><button type="button" class="btn small" data-result-page="${pageIndex+1}" ${pageIndex+1>=pageCount?'disabled':''}>下一页</button></div><p class="small-text">0表示实际计算为零；空值不等于0。排序保留原始数值精度，比例不会跨组相加。</p><div class="actions"><button class="btn small" data-action="export-csv">导出本次全部结果</button><button class="btn small" data-action="export-visible" ${rows.length?'':'disabled'}>导出筛选结果 ${rows.length} 组</button><button class="btn small" data-reuse="${h(r.id)}">调整条件再查询</button></div>`:`${empty('当前范围没有匹配的记录','可以保留当前条件返回调整日期或范围；没有记录不会显示成数值0。')}<button class="btn" data-reuse="${h(r.id)}">返回调整条件</button>`}`;
}
function renderMetrics(){const metrics=state.workspace.metrics.filter(m=>(!state.favoritesOnly||(state.workspace.favorites||[]).includes(m.id))&&(state.metricStatus==='all'||m.status===state.metricStatus)&&`${m.name} ${m.description} ${m.aliases.join(' ')} ${m.source}`.toLowerCase().includes(state.metricSearch.toLowerCase())).sort((a,b)=>Number((state.workspace.favorites||[]).includes(b.id))-Number((state.workspace.favorites||[]).includes(a.id)));$('#content').innerHTML=header('数据指标字典','只连接 d_root_project_marketing_db；把筛选范围与计算数值分开配置。','<button class="btn primary" data-action="new-metric">＋ 新建指标</button>')+semanticIntro()+`<div class="toolbar"><input id="metric-search" aria-label="搜索指标" placeholder="搜索指标名称、别名、定义或数据表" value="${h(state.metricSearch)}"><select id="metric-status" aria-label="筛选指标状态">${options([['all','全部状态'],['active','已启用'],['draft','草稿']],state.metricStatus)}</select><label class="check-inline"><input type="checkbox" id="favorites-only" ${state.favoritesOnly?'checked':''}>只看常用</label><span class="muted small-text">${metrics.length} 个指标</span></div><div class="table-wrap"><table><thead><tr><th>指标 / 业务定义</th><th>计算方式</th><th>状态</th><th>维护人</th><th>操作</th></tr></thead><tbody>${metrics.map(m=>`<tr><td><strong>${h(m.name)}</strong><small>${h(m.description)}</small><small>${h(m.aliases.join(' / '))}</small></td><td>${h(aggs[m.aggregation])}<small>${h(m.unit)} · v${m.revision}</small></td><td><span class="pill ${m.status==='draft'?'draft':''}">${m.status==='active'?'已启用':'草稿'}</span></td><td>${h(m.owner||'未填写')}</td><td><div class="actions"><button class="btn small" data-favorite="${m.id}" aria-pressed="${(state.workspace.favorites||[]).includes(m.id)}">${(state.workspace.favorites||[]).includes(m.id)?'★ 常用':'☆ 加入常用'}</button><button class="btn small" data-edit="${m.id}">编辑定义</button><button class="btn small" data-use="${m.id}">使用</button></div></td></tr>`).join('')}</tbody></table>${metrics.length?'':empty('没有匹配的指标','可以调整搜索条件，或创建一个新指标。')}</div><div class="callout">范围字段控制“哪些数据”；数值字段控制“计算什么”。点击率、ROI、单位成本用汇总后的分子和分母计算，不能直接加总平台比率。</div>`;}
function renderHistory(){const queries=state.workspace.queries.filter(q=>`${q.name} ${q.request} ${q.summary}`.toLowerCase().includes((state.historySearch||'').toLowerCase()));$('#content').innerHTML=header('已保存的分析','每次确认都会保存当时的指标版本、业务口径和 SQL，后续修改字典不会改写历史。')+`<div class="toolbar"><input id="history-search" aria-label="搜索已保存的分析" placeholder="搜索分析名称、业务问题或统计范围" value="${h(state.historySearch||'')}"><span>找到 ${queries.length} 条分析</span></div><div class="table-wrap"><table><thead><tr><th>指标</th><th>统计范围</th><th>版本 / 保存时间</th><th>操作</th></tr></thead><tbody>${queries.map(q=>`<tr><td><strong>${h(q.name)}</strong><small>${h(q.request)}</small></td><td>${h(q.definition.startDate)} → ${h(inclusiveEnd(q.definition.endDate))}（含当天）<small>${h(grains[q.definition.grain])} · ${h(q.definition.dimension||'不分组')}</small></td><td>v${q.metric.revision}<small>${new Date(q.createdAt).toLocaleString('zh-CN')}</small></td><td><button class="btn small" data-query="${q.id}">查看 / 执行</button></td></tr>`).join('')}</tbody></table>${queries.length?'':empty(state.historySearch?'没有匹配的分析':'还没有保存的分析',state.historySearch?'换个关键词试试。':'在智能取数中确认一次口径，它就会保存在这里。')}</div>${state.confirmed?queryPanel(state.confirmed):''}`;}
function renderFields(){$('#content').innerHTML=header('数据字段字典','明确每个字段的业务用途；数字类型不等于数值度量。','<button class="btn" data-action="reload-tables">刷新数据表</button>')+`<div class="field-layout"><section class="panel source-panel"><input id="source-search" placeholder="搜索表名、库名或注释" aria-label="搜索数据表"><div id="source-list" class="field-search-list">${tableButtons(state.tables)}</div></section><section class="panel source-detail" id="source-detail">${state.source?sourceDetail():empty('选择一张数据表','区分范围条件、数值度量和不可直接相加的派生比率。')}</section></div>`;if(!state.tables.length)loadTables();}
function tableButtons(tables){return tables.map(t=>`<button class="source-button ${state.source?.id===t.id?'active':''}" data-source="${h(t.id)}"><strong>${h(t.comment||t.tableName)}</strong><small>${h(t.id)}</small></button>`).join('')||'<div class="empty">没有数据表，请刷新或检查数据库连接。</div>';}
function sourceDetail(){
 const s=state.source,counts=Object.fromEntries(Object.keys(roleLabels).map(r=>[r,s.columns.filter(c=>c.role===r).length]));
 const fields=s.columns.filter(c=>(state.fieldRole==='all'?c.role!=='technical':c.role===state.fieldRole)&&(!state.fieldSearch||`${c.businessLabel} ${c.name} ${c.businessExplanation}`.toLowerCase().includes(state.fieldSearch.toLowerCase()))&&(!state.pendingOnly||c.meaningStatus!=='confirmed'));
 return `<div class="panel-title"><div><h2>${h(s.comment||s.id.split('.')[1])}</h2><details><summary>查看数据表标识</summary><code>${h(s.id)}</code></details></div><button class="btn small" data-action="refresh-source">同步字段</button></div><div class="callout"><strong>不认识字段？先看真实记录，再确认含义。</strong><p>点击“看数据 / 确认含义”核对单个字段；勾选最多6个相似字段，可在同一条记录中比较它们的数值。确认后的名称和解释会用于选指标、筛选与计算。</p></div><div class="role-overview"><div class="scope-card"><span>决定范围</span><strong>${counts.scope+counts.time}</strong><p>哪一天、哪个账户、哪个计划</p></div><div class="measure-card"><span>真正数值</span><strong>${counts.measure}</strong><p>花了多少钱、展示或点击了多少次</p></div><div class="derived-card"><span>需特殊计算</span><strong>${counts.derived+counts.snapshot}</strong><p>比例要重算，余额不能跨天相加</p></div></div><div class="grain-note ${s.semantics?.kind==='snapshot'?'warning':''}"><strong>${s.semantics?.kind==='snapshot'?'同一天可能反复采集':'核对一条记录代表什么'}</strong><span>${s.semantics?.kind==='snapshot'?'下面展示采集到的原始记录。同一账户或计划可能重复出现，不能把累计值直接相加。':'结合日期、账户和计划检查，避免把不同统计范围的数据重复计算。'}</span></div><div class="field-toolbar"><input id="field-search" aria-label="搜索字段" placeholder="搜索：花费、点击、账户或字段编号" value="${h(state.fieldSearch||'')}"><label><input type="checkbox" id="pending-only" ${state.pendingOnly?'checked':''}>只看待确认</label><button class="btn" data-action="compare-fields">对比选中字段（${state.compareFields?.length||0}/6）</button></div><div class="role-tabs"><button data-role="all" class="${state.fieldRole==='all'?'selected':''}">全部业务字段</button>${Object.entries(roleLabels).map(([r,label])=>`<button data-role="${r}" class="${state.fieldRole===r?'selected':''}">${label} <b>${counts[r]}</b></button>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>对比</th><th>业务名称 / 确认状态</th><th>用来做什么</th><th>用户能理解的解释</th><th>核对数据</th></tr></thead><tbody>${fields.map(c=>`<tr><td><input type="checkbox" aria-label="对比 ${h(c.name)}" data-compare-field="${h(c.name)}" ${(state.compareFields||[]).includes(c.name)?'checked':''} ${c.sensitivity==='restricted'?'disabled':''}></td><td><strong>${h(c.businessLabel||c.label)}</strong><small>${h(c.guideBasis)}</small><small><code>${h(c.name)}</code></small></td><td><span class="role-tag ${c.role}">${h(roleLabels[c.role])}</span><small>${h(c.usageExplanation)}</small></td><td class="field-explanation">${h(c.businessExplanation)}<small>单位：${h(c.unit||'尚未确认')}</small></td><td><button class="btn small" data-field="${h(c.name)}">看数据 / 确认含义</button></td></tr>`).join('')}</tbody></table>${fields.length?'':empty('没有符合条件的字段','调整搜索词或关闭“只看待确认”。')}</div>`;
}
async function loadTables(){try{state.tables=await api('/api/tables?refresh=true');if($('#source-list'))$('#source-list').innerHTML=tableButtons(state.tables);}catch(e){toast(e.message);}}
function renderSettings(){const s=state.workspace.settings;$('#content').innerHTML=header('连接与模型','配置会在本机持久保存。密钥不返回页面，模型调用由服务端发起。')+`<div class="settings-grid"><section class="panel"><div class="panel-title"><h2>模型连接</h2><span class="pill ${s.configured?'':'draft'}">${s.configured?'已配置':'未配置'}</span></div><form id="settings-form"><div class="form-grid"><div class="full">${label('API 地址',`<input id="model-url" type="url" required value="${h(s.baseUrl)}">`,'兼容 Chat Completions 的 HTTPS 服务地址。')}</div><div class="full">${label('模型名称',`<input id="model-name" required value="${h(s.model)}">`)}</div><div class="full">${label('API Key',`<input id="model-key" type="password" autocomplete="new-password" placeholder="${s.configured?'已保存；留空保持现有密钥':'填写模型 API Key'}">`)}</div></div><div class="actions" style="margin-top:24px"><button class="btn primary">保存配置</button><button type="button" class="btn" data-action="test-model">测试已保存的连接</button></div><div id="model-test-result" class="small-text" style="margin-top:16px"></div><div id="form-error" class="inline-error"></div></form></section><div><section class="panel"><div class="panel-title"><h2>数据库连接</h2><button class="btn small" data-action="health">重新检测</button></div><div class="kv"><span>连接状态</span><strong>${state.health?.database.connected?'已连接数据库':'未连接'}</strong></div><div class="kv"><span>执行方式</span><strong>只读事务 · 12 秒上限</strong></div><div class="kv"><span>数据表</span><strong>仅数据库内业务表与视图</strong></div><p class="small-text" style="margin-top:18px">连接信息保存在服务端 .env 文件。库名固定为 d_root_project_marketing_db；跨库请求由服务端拒绝。</p></section><section class="panel"><h3>模型实际做什么</h3><p class="small-text">理解问题、检索最新指标字典、对照同步过的字段提出建议并澄清歧义。计算与 SQL 生成由已保存的结构化定义决定。</p><p class="small-text">调用失败会显示真实错误，保留你的问题供重试。</p></section></div></div>`;}
function openModal(title,body,footer=''){const modal=$('#modal');$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭">×</button></div>${body}${footer}`;if(!modal.open)modal.showModal();modal.scrollTop=0;const modalBody=modal.querySelector('.modal-body');if(modalBody)modalBody.scrollTop=0;}
async function openMetric(id,suggestion){
 if(!state.tables.length)await loadTables();
 const old=state.workspace.metrics.find(m=>m.id===id);
 state.editMetric=old?structuredClone(old):{name:'',description:'',aliases:[],source:state.source?.id||state.workspace.metrics[0]?.source||state.tables[0]?.id,aggregation:'sum',denominatorField:'',multiplier:1,snapshotPolicy:'none',valueField:'',distinctFields:[],timeField:'',dimension:'',scale:1,unit:'',owner:'',status:'draft',filters:[],notes:'',...suggestion};
 const m=state.editMetric;
 if(!state.tables.some(t=>t.id===m.source))m.source=state.tables[0]?.id;
 if(!m.source)throw new Error('未能读取数据表，请先检查数据库连接');
 const source=await api('/api/source?id='+encodeURIComponent(m.source));state.editorSource=source;
 openModal(old?'编辑指标定义':'新建业务指标',`<form id="metric-form"><div class="modal-body"><div class="form-grid">${label('指标名称 *',`<input name="name" value="${h(m.name)}" required maxlength="100" placeholder="例如：指定账户的投放消耗">`)}${label('业务别名',`<input name="aliases" value="${h((m.aliases||[]).join('，'))}" placeholder="多个别名用逗号分隔">`)}<div class="full">${label('业务定义 *',`<textarea name="description" required placeholder="说明统计对象、计算方法，以及包含和排除哪些情况">${h(m.description)}</textarea>`)}</div></div><div class="form-section"><h3><span class="badge-number">1</span>选择数据来源</h3>${label('数据表 / 视图',`<select id="metric-source" name="source">${options(state.tables.map(t=>[t.id,`${t.comment||t.tableName} · ${t.id}`]),m.source)}</select>`)}<div id="mapping-fields" style="margin-top:20px">${mappingFields(m,source)}</div></div><div class="form-section"><div class="panel-title"><h3><span class="badge-number">2</span>筛选条件</h3><button type="button" class="btn small" data-action="add-filter">＋ 添加条件</button></div><p class="small-text">这里只放范围字段，例如账户、部门、计划、业务目标。数值字段在计算区选择。</p><div id="filters">${(m.filters||[]).map(f=>filterRow(f,source)).join('')}</div></div><div class="form-section"><h3><span class="badge-number">3</span>发布与口径说明</h3><div class="form-grid">${label('维护人',`<input name="owner" value="${h(m.owner)}" placeholder="团队或负责人">`)}${label('状态',`<select name="status">${options([['draft','草稿 · 待完善'],['active','启用 · 可生成 SQL']],m.status)}</select>`)}<div class="full">${label('口径说明 / 已知限制',`<textarea name="notes" placeholder="例如：消耗原单位为元；一行一账户一天；ROI先汇总再计算">${h(m.notes)}</textarea>`)}</div></div></div><div id="form-error" class="inline-error"></div></div><div class="modal-footer"><div>${old?`<button type="button" class="btn danger" data-delete="${old.id}">删除指标</button>`:'<span class="small-text muted">保存到服务端字典</span>'}</div><div class="actions"><button type="button" class="btn" data-action="close-modal">取消</button><button class="btn primary">保存指标定义</button></div></div></form>`);
 syncAggregationControls();
}
function syncAggregationControls(){const agg=$('#aggregation')?.value;if(!agg)return;const den=$('#denominator-field'),value=$('#value-field');den.closest('label').hidden=agg!=='ratio_of_sums';den.disabled=agg!=='ratio_of_sums';value.disabled=agg.startsWith('count');for(const name of ['scale','multiplier']){const el=$(`#metric-form [name="${name}"]`);el.disabled=agg.startsWith('count');}}
function mappingFields(m,s){
 return `<div class="metric-design-grid"><section class="design-scope"><div class="design-heading"><span class="role-tag scope">A · 范围</span><h3>统计哪些数据？</h3><p>选时间、账户、计划；与数值计算分开。</p></div><div class="form-stack">${label('业务日期 *',`<select name="timeField" required>${fieldOptions(s,m.timeField,'time')}</select>`,'统计归属的日期，不使用采集时间。')}${label('默认分组（可不分组）',`<select name="dimension">${fieldOptions(s,m.dimension,'scope',true)}</select>`,'决定按账户、计划还是部门展示；不改变筛选范围。')}<div class="scope-examples"><span class="small-text">可配置的范围字段</span><div>${s.columns.filter(c=>c.role==='scope').slice(0,9).map(c=>`<span>${h(c.businessLabel||c.label)}</span>`).join('')}</div></div>${s.semantics?.kind==='snapshot'?label('快照处理',`<select name="snapshotPolicy">${options([['none','尚未确定（仅可保存草稿）'],['latest_per_day','每个业务实体每天取最新快照']],m.snapshotPolicy||'none')}</select>`,s.semantics.snapshotField?'依据 '+s.semantics.snapshotField+' 取最新值，之后再聚合。':'此表尚无法识别快照唯一键，先整理日表再启用。'):'<input type="hidden" name="snapshotPolicy" value="none">'}</div></section><section class="design-measure"><div class="design-heading"><span class="role-tag measure">B · 数值</span><h3>计算什么？</h3><p>只提供业务数值，账户 ID 不会出现在这里。</p></div><div class="form-stack">${label('计算方式',`<select name="aggregation" id="aggregation">${options(Object.entries(aggs),m.aggregation)}</select>`)}${label('数值字段 / 分子',`<select name="valueField" id="value-field">${fieldOptions(s,m.valueField,'number',true)}</select>`,'求和选消耗或数量；计数不需要数值字段。')}${label('分母（仅“分子合计 ÷ 分母合计”使用）',`<select name="denominatorField" id="denominator-field">${fieldOptions(s,m.denominatorField,'number',true)}</select>`,'点击率选：点击量 ÷ 曝光量。ROI 选：成交金额 ÷ 消耗。')}<div class="form-grid">${label('换算除数',`<input name="scale" type="number" step="any" min="0.000001" value="${h(m.scale)}" required>`)}${label('输出倍数',`<input name="multiplier" type="number" step="any" min="0.000001" value="${h(m.multiplier||1)}" required>`,'百分比填100，其他通常填1。')}</div>${label('结果单位',`<input name="unit" value="${h(m.unit)}" placeholder="元 / 次 / % / 倍">`)}<button type="button" class="btn" data-action="preview-editor">查看所选字段的真实数据</button><div class="formula-note">平台现成的点击率、ROI 不能直接求和，也不简单平均。系统会汇总分子、分母后重算，分母为零返回空值。</div></div></section></div><details class="definition-detail"><summary>去重计数的业务键（仅去重或按数量相除时使用）</summary><div class="check-list">${s.columns.filter(c=>c.role==='scope').map(c=>`<label><input type="checkbox" name="distinctFields" value="${h(c.name)}" ${(m.distinctFields||[]).includes(c.name)?'checked':''}><span>${h(c.label)} <code>${h(c.name)}</code></span></label>`).join('')}</div></details>`;
}
function filterRow(f,s){return `<div class="filter-row" data-source="${h(s?.id)}"><select class="filter-field" aria-label="范围字段">${fieldOptions(s,f.field,'filter')}</select><select class="filter-operator" aria-label="范围运算符">${options(Object.entries(opNames),f.operator||'eq')}</select><input class="filter-value" data-selected-values="${h(JSON.stringify(Array.isArray(f.value)?f.value:[]))}" data-raw-snapshot="${h(Array.isArray(f.value)?f.value.join('，'):'')}" value="${h(Array.isArray(f.value)?f.value.join('，'):f.value)}" placeholder="匹配值；多个值以逗号分隔" aria-label="范围值"><button type="button" class="btn small" data-action="field-values">取值</button><button type="button" class="icon-btn" data-action="remove-filter" aria-label="移除条件">×</button></div>`;}
async function saveMetric(form){const data=Object.fromEntries(new FormData(form));data.aliases=data.aliases.split(/[,，]/).map(v=>v.trim()).filter(Boolean);data.distinctFields=new FormData(form).getAll('distinctFields');data.scale=Number(data.scale||1);data.multiplier=Number(data.multiplier||1);data.filters=scopeRows($('#filters'));const old=state.editMetric;if(old.id)data.revision=old.revision;const saved=await api('/api/metrics'+(old.id?'/'+old.id:''),data,old.id?'PUT':'POST');await refresh();$('#modal').close();toast('指标已保存，助手将使用最新定义');if(state.view==='assistant'&&state.analysis&&!state.analysis.metricId){state.analysis.metricId=saved.id;state.analysis.questions=[];}render();}
async function openField(name){
 const c=state.source.columns.find(c=>c.name===name);state.fieldEvidence=null;
 openModal('看真实数据，确认字段含义',`<form id="field-form"><div class="modal-body"><div class="field-guide"><span class="pill">${h(c.guideBasis)}</span><h3>${h(c.businessLabel)}</h3><p>${h(c.businessExplanation)}</p><p>${h(c.usageExplanation)}</p></div><button type="button" class="btn" data-explain-field="${h(name)}">帮我解释含义和相似字段的区别</button><div id="field-explanation"></div>${sampleDateControls(state.source,'field-sample')}<div id="field-evidence"><div class="busy-note">正在读取真实记录…</div></div><div id="value-meaning-editor"></div><button type="button" class="btn small" data-reload-evidence="${h(name)}">重新读取样例</button><h3 style="margin-top:24px">这些值在你的业务中代表什么？</h3><p>把名称改成同事一看就懂的话；解释要说明统计对象、单位，以及容易混淆的地方。系统解释只是起点。</p><input type="hidden" name="name" value="${h(c.name)}"><div class="form-grid">${label('业务名称',`<input name="label" required maxlength="100" value="${h(c.businessLabel==='待命名字段'?'':c.businessLabel)}" placeholder="例如：广告被点击的次数">`)}${label('这些值的用途',`<select name="role">${options(Object.entries(roleLabels),c.role)}</select>`)}${label('计量单位',`<input name="unit" maxlength="30" value="${h(c.unit)}" placeholder="元、次、个；编号或名称可留空">`)}${label('数据可见性',`<select name="sensitivity">${options([['normal','普通'],['internal','内部'],['restricted','受限 · 不展示样例']],c.sensitivity||'internal')}</select>`)}<div class="full">${label('给其他使用者的解释',`<textarea name="description" required maxlength="2000" placeholder="例如：广告被点击的次数，同一人多次点击会重复计数，不是点击人数。">${h(c.description||c.businessExplanation)}</textarea>`)}</div></div><details><summary>技术信息（无需阅读即可完成确认）</summary><p><code>${h(c.name)}</code> · ${h(c.type)}</p><p>${h(c.comment)}</p></details><div id="form-error" class="inline-error"></div></div><div class="modal-footer"><button class="btn" type="submit">保存为待确认</button><button class="btn primary" type="submit" id="confirm-meaning" data-confirm-meaning="true" disabled>我已核对真实值，确认含义</button></div></form>`);
 await loadFieldEvidence(name);
}
async function loadFieldEvidence(name){const requestId=state.fieldEvidenceRequest=(state.fieldEvidenceRequest||0)+1;const priorLabels=Object.fromEntries([...document.querySelectorAll('#value-meaning-editor [data-value-label]')].map(el=>[el.dataset.valueLabel,el.value]));const source=state.source.id;const slot=$('#field-evidence');state.fieldEvidence=null;$('#confirm-meaning').disabled=true;slot.innerHTML='<div class="busy-note">正在读取真实记录…</div>';try{const dateInput=sampleDateInput('field-sample');const r=await api('/api/evidence',{source,fields:[name],...dateInput});if(!slot.isConnected||requestId!==state.fieldEvidenceRequest||$('#field-form [name="name"]')?.value!==name)return;slot.innerHTML=evidenceContent(r);state.fieldEvidence=r.evidenceId;$('#confirm-meaning').disabled=!r.rows.length;const c=r.columns.find(c=>c.name===name);if(c?.role==='scope'){const values=[...new Set(r.rows.map(row=>row[name]).filter(v=>v!==null&&v!==''))].slice(0,12);$('#value-meaning-editor').innerHTML=values.length?`<details class="value-meaning-details"><summary>这些编号或代码看不懂？给真实值加一个业务名称</summary><p>只填写你已核对过的含义。保存后，筛选候选和样例会显示这个名称；查询仍使用原值。</p>${values.map(value=>`<label class="value-meaning-row"><code>${h(value)}</code><input data-value-label="${h(value)}" maxlength="100" value="${h(priorLabels[value]??c.valueLabels?.[value]??'')}" placeholder="它在业务中叫什么？不确定就留空"></label>`).join('')}</details>`:'';}}catch(e){if(slot.isConnected)slot.innerHTML=`<div class="callout warning">${h(e.message)}。可以先保存解释为待确认；有真实数据后再确认。</div>`;}}
function sampleDateControls(source,prefix,values={}){const time=source.columns.find(c=>c.name===values.timeField)||source.columns.find(c=>c.role==='time');if(!time)return '';return `<div class="sample-dates"><strong>想核对某一天？可选日期后重新读取</strong><div class="form-grid">${label('从哪天开始',`<input type="date" id="${prefix}-start" value="${h(values.startDate||'')}">`)}${label('到哪天（包含当天）',`<input type="date" id="${prefix}-end" value="${h(inclusiveEnd(values.endDate))}">`)}</div><input type="hidden" id="${prefix}-time" value="${h(time.name)}"><small>不选日期则从全表取样；选同一天即可核对一天的数据。</small></div>`;}
function sampleDateInput(prefix){const startDate=$('#'+prefix+'-start')?.value,endDate=exclusiveEnd($('#'+prefix+'-end')?.value);return startDate||endDate?{startDate,endDate,timeField:$('#'+prefix+'-time').value}:{};}
function evidenceContent(r){return `<div class="evidence-guides">${($('#modal').open&&$('#field-form')?[]:r.columns).filter(c=>(r.requestedFields||[]).includes(c.name)).map(c=>`<section><strong>${h(c.businessLabel||c.label)}</strong><span class="pill">${h(c.guideBasis||'待确认')}</span><p>${h(c.businessExplanation||c.roleReason)}</p><small>${h(['scope','time','technical'].includes(c.role)?'识别记录，不参与求和':'单位：'+(c.unit||'尚未确认'))} · ${h(c.usageExplanation||'')}</small>${!($('#modal').open&&($('#metric-form')||$('#field-form')))?`<button type="button" class="btn small" data-inspect-field="${h(c.name)}" data-inspect-source="${h(r.source)}">核对并修改这项含义</button>`:''}</section>`).join('')}</div><div class="evidence-summary"><strong>真实记录 · ${r.rows.length} 条</strong><span>日期：${h(r.scope)}</span><span>筛选：${r.filters?.length?r.filters.map(f=>h(`${r.filterLabels?.[f.field]||r.columns.find(c=>c.name===f.field)?.businessLabel||f.field} ${opNames[f.operator]} ${Array.isArray(f.value)?f.value.join('、'):f.value??''}`)).join('；'):'未额外限制'}</span><small>读取于 ${h(new Date(r.sampledAt).toLocaleString('zh-CN'))}</small></div><p class="small-text">${h(r.note)}</p>${r.snapshot?'<div class="callout warning">这些是重复采集的原始值，尚未按每天最新记录去重，不是最终汇总结果。</div>':''}${r.rows.length?`${renderProfiles(r)}<div class="table-wrap evidence-table"><table><thead><tr>${r.columns.map(c=>`<th>${h(c.businessLabel||c.label||c.name)}<small>${h(c.name)}</small><small>${h(['scope','time','technical'].includes(c.role)?'用于定位记录，不求和':c.unit?'单位：'+c.unit:'单位尚未确认')}</small></th>`).join('')}</tr></thead><tbody>${r.rows.map(row=>`<tr>${r.columns.map(c=>`<td>${row[c.name]===null?'<span class="muted">未记录（空值）</span>':row[c.name]===''?'<span class="muted">空文本</span>':c.valueLabels?.[row[c.name]]?`${h(c.valueLabels[row[c.name]])}<small>${h(row[c.name])}</small>`:h(row[c.name])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="small-text">横向看同一行：日期与账户相同，便于比较所选字段。数据保留原始精度。</p>`:empty('这个范围没有记录','可以关闭预览后扩大日期范围或减少筛选。当前没有样例可用于确认字段含义。')}`;}
async function previewEvidence(input,title){let dialog=$('#evidence-modal');if(!dialog){dialog=document.createElement('dialog');dialog.id='evidence-modal';document.body.append(dialog);}dialog.innerHTML=`<div class="modal-head"><h2>${h(title)}</h2><button type="button" class="icon-btn" aria-label="关闭数据预览" id="close-evidence">×</button></div><div class="modal-body" id="evidence-body"><div class="busy-note">正在读取真实记录…</div></div>`;$('#close-evidence').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();const slot=$('#evidence-body');try{const r=await api('/api/evidence',input);if(slot.isConnected){slot.innerHTML=sampleDateControls({columns:r.columns},'preview-sample',input)+`<button type="button" class="btn small" id="refresh-preview-sample">按上方日期重新取样</button>`+evidenceContent(r);$('#refresh-preview-sample').onclick=()=>{const next={...input};delete next.startDate;delete next.endDate;delete next.timeField;previewEvidence({...next,...sampleDateInput('preview-sample')},title);};}}catch(e){if(slot.isConnected)slot.innerHTML=`<div class="callout error">${h(e.message)}</div><p>关闭后调整字段或范围，再重试。</p>`;}}
async function ask(query){
 if(state.busy)return;state.busy=true;state.analysisError='';state.confirmed=null;state.result=null;
 const history=state.messages.slice(-28).map(m=>({role:m.role,content:m.content}));
 state.messages.push({role:'user',content:query});state.analysis=null;renderAssistant();
 try{const result=await api('/api/analyze',{query,messages:history});state.analysis=result;state.messages.push({role:'assistant',summary:result.summary,content:JSON.stringify(result)});}catch(e){state.analysisError=e.message;toast(e.message);}finally{state.busy=false;persistDraft();if(state.view==='assistant')renderAssistant();}
}
async function confirmQuery(form,execute=false){
 if(state.confirming){toast('正在保存本次分析，请稍候');return;}state.confirming=true;
 const buttons=[...form.querySelectorAll('button')],disabled=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);
 try{const m=state.workspace.metrics.find(m=>m.id===$('#q-metric').value);if(!m)throw new Error('请先选择或创建指标');captureDraft();const definition={startDate:$('#q-start').value,endDate:exclusiveEnd($('#q-end').value),grain:$('#q-grain').value,timeField:$('#q-time').value,dimension:$('#q-dimension').value,scopeFilters:scopeRows($('#query-scope'))};
 const payload={metricId:m.id,revision:state.analysis.metricRevision||m.revision,definition,request:state.messages.filter(m=>m.role==='user').map(m=>m.content).join('；')};
 const key=JSON.stringify(payload);if(state.saveAttempt?.key!==key)state.saveAttempt={key,requestId:crypto.randomUUID()};const saved=await api('/api/confirm',{...payload,requestId:state.saveAttempt.requestId});state.confirmed=saved;state.result=null;persistDraft();await refresh();
 if(state.view==='assistant'&&form.isConnected){renderAssistant();$('#saved-query').scrollIntoView({behavior:'smooth',block:'start'});if(execute)await runQuery($('#saved-query [data-mode="full"]'));}else toast('分析已保存，可在已保存的分析中查看');
 }finally{state.confirming=false;buttons.forEach((b,i)=>{if(b.isConnected)b.disabled=disabled[i];});}
}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadResultChart(){
 const svg=$('#result-chart-svg'),r=state.result;if(!svg||!r)return;const ns='http://www.w3.org/2000/svg',q=state.workspace.queries.find(q=>q.id===r.id);const box=svg.viewBox.baseVal,root=document.createElementNS(ns,'svg');root.setAttribute('xmlns',ns);root.setAttribute('viewBox',`0 0 ${box.width} ${box.height+105}`);root.setAttribute('font-family','Arial, sans-serif');const bg=document.createElementNS(ns,'rect');bg.setAttribute('width','100%');bg.setAttribute('height','100%');bg.setAttribute('fill','#fff');root.append(bg);const title=document.createElementNS(ns,'title');title.textContent=q?.name||'指标图表';root.append(title);const desc=document.createElementNS(ns,'desc');desc.textContent=q?.summary||'';root.append(desc);const style=document.createElementNS(ns,'style');style.textContent=':root{--chart-grid:#e5e7eb;--chart-zero:#9ca3af;--chart-text:#111827;--chart-label:#374151;--chart-muted:#6b7280;--chart-pos:#374151;--chart-neg:#9ca3af;--chart-point-ring:#ffffff}';root.append(style);
 const lines=[q?.name||'指标图表',`${r.start} 至 ${inclusiveEnd(r.end)} · ${r.mode==='sample'?'开始日试跑':'确认范围'}${r.truncated?' · 返回结果已截断':''}`,`单位：${r.unit||'未填写'}${$('#chart-series')?' · 趋势分组：'+$('#chart-series').selectedOptions[0].textContent:''}${state.resultSearch?' · 搜索：'+state.resultSearch:''}`];lines.forEach((line,i)=>{const text=document.createElementNS(ns,'text');text.setAttribute('x','16');text.setAttribute('y',String(28+i*27));text.setAttribute('font-size',i===0?'20':'13');text.setAttribute('fill','#21493b');text.textContent=line.length>78?line.slice(0,78)+'…':line;root.append(text);});const chart=svg.cloneNode(true);chart.setAttribute('x','0');chart.setAttribute('y','105');chart.setAttribute('width',String(box.width));chart.setAttribute('height',String(box.height));root.append(chart);download('指标图表.svg',new XMLSerializer().serializeToString(root),'image/svg+xml');
}
async function openResultEvidence(index){
 const r=state.result,row=r?.rows[index];if(!row)return;
 let dialog=$('#result-evidence-modal');if(!dialog){dialog=document.createElement('dialog');dialog.id='result-evidence-modal';dialog.className='result-evidence-modal';document.body.append(dialog);}const label=[row.period,row.dimension].filter(v=>v!==undefined).map(v=>v===null?'未填写分组':v).join(' · ')||'当前范围';
 dialog.innerHTML=`<div class="modal-head"><h2>核对这项结果的原始记录</h2><button type="button" class="icon-btn" aria-label="关闭结果核对" id="close-result-evidence">×</button></div><div class="modal-body"><div class="number-card"><span>${h(label)}</span><strong>${h(formatValue(row.value))}<small>${h(r.unit||'')}</small></strong><p>这里显示的是已查询的统计结果，下方按相同条件重新读取当前原始记录；数据可能与上次查询时不同。</p></div><div id="result-evidence-content"><div class="busy-note">正在按已保存的口径读取数据…</div></div></div>`;
 $('#close-result-evidence').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();const slot=$('#result-evidence-content');
 try{const data=await api('/api/queries/'+r.id+'/evidence',{mode:r.mode,...('period' in row?{period:row.period}:{}),...('dimension' in row?{dimension:row.dimension}:{})});if(slot.isConnected)slot.innerHTML=evidenceContent(data);}catch(e){if(slot.isConnected)slot.innerHTML=`<div class="callout error">${h(e.message)}</div><button type="button" class="btn" data-result-row="${index}">重新读取</button>`;}
}
async function runQuery(button){
 if(state.runningQuery){toast('查询正在执行，请等待本次结果');return;}const id=button.dataset.run,mode=button.dataset.mode;state.runningQuery=id;state.resultSearch='';state.resultSort='original';state.resultPage=0;state.chartSeries='';
 const slot=$('#query-result');if(slot)slot.innerHTML='<div class="busy-note"><span class="spinner"></span>正在查询真实数据，可切换页面，结果返回后仍会保留。</div>';document.querySelectorAll('[data-run]').forEach(b=>b.disabled=true);
 try{const r=await api(`/api/queries/${id}/run`,{mode});state.lastResults=state.lastResults||{};state.lastResults[id]={...r,id,executedAt:new Date().toLocaleTimeString('zh-CN')};if(state.confirmed?.id===id){state.result=state.lastResults[id];if($('#query-result'))$('#query-result').innerHTML=resultPanel(state.result);}else toast('查询已完成，可从已保存的分析查看');}
 catch(e){if(state.confirmed?.id===id&&$('#query-result'))$('#query-result').innerHTML=`<div class="callout error">${h(e.message)}</div><div class="actions"><button class="btn" data-run="${h(id)}" data-mode="${h(mode)}">重试查询</button><button class="btn" data-reuse="${h(id)}">调整条件</button></div>`;else toast(e.message);}
 finally{state.runningQuery=null;document.querySelectorAll('[data-run]').forEach(b=>b.disabled=false);}
}
document.addEventListener('click',async event=>{
 const drill=event.target.closest('[data-result-row]');if(drill){await openResultEvidence(Number(drill.dataset.resultRow));return;}
 const b=event.target.closest('button');if(!b||b.disabled)return;
 if(b.id==='theme-toggle'){toggleTheme();return;}
 if(b.form && b.type==='submit')return;
 if(b.dataset.nav){navigate(b.dataset.nav);return;}
 if(b.dataset.run){await runQuery(b);return;}
 await busy(b,async()=>{
  if(b.dataset.resultPage!==undefined){state.resultPage=Number(b.dataset.resultPage);$('#query-result').innerHTML=resultPanel(state.result);return;}
  if(b.dataset.favorite){const favorite=!(state.workspace.favorites||[]).includes(b.dataset.favorite);const r=await api('/api/favorites/'+b.dataset.favorite,{favorite},'PUT');state.workspace.favorites=r.favorites;renderMetrics();return;}
  if(b.dataset.explainField){const slot=$('#field-explanation'),source=state.source.id,name=b.dataset.explainField;slot.innerHTML='<div class="busy-note">正在整理业务解释，最长约60秒…</div>';try{const r=await api('/api/field-explanation',{source,field:name});if(!slot.isConnected)return;state.explanationDraft=r;slot.innerHTML=`<div class="callout"><strong>${h(r.label)}</strong><p>${h(r.description)}</p>${r.questions.length?`<p>核对时重点看：</p><ul>${r.questions.map(q=>`<li>${h(q)}</li>`).join('')}</ul>`:''}<small>${h(r.basis)}</small><div class="actions"><button type="button" class="btn small" data-action="apply-explanation">填入编辑区，供我修改</button>${r.compareFields.length?`<button type="button" class="btn small" data-explanation-compare="${h(JSON.stringify([name,...r.compareFields]))}">看相似字段的真实数值</button>`:''}</div></div>`;}catch(e){if(slot.isConnected)slot.innerHTML=`<div class="callout warning">${h(e.message)}。已有真实样例和手动编辑仍可使用。</div>`;}return;}
  if(b.dataset.explanationCompare){await previewEvidence({source:state.source.id,fields:JSON.parse(b.dataset.explanationCompare)},'对照相似字段的实际数值');return;}
  if(b.dataset.inspectField){captureDraft();$('#evidence-modal')?.close();$('#result-evidence-modal')?.close();state.source=await api('/api/source?id='+encodeURIComponent(b.dataset.inspectSource));await openField(b.dataset.inspectField);return;}
  if(b.dataset.previewMetric){captureDraft();const m=state.workspace.metrics.find(m=>m.id===b.dataset.previewMetric);const fields=[...new Set([m.valueField,m.denominatorField,...(m.distinctFields||[]),m.timeField].filter(Boolean))].slice(0,6);await previewEvidence({source:m.source,metricId:m.id,fields,...($('#q-start')?.value&&$('#q-end')?.value?{startDate:$('#q-start').value,endDate:exclusiveEnd($('#q-end').value),timeField:$('#q-time').value}:{}),scopeFilters:$('#query-scope')?scopeRows($('#query-scope')):[]},'核对指标使用的原始数据');return;}
  if(b.dataset.reloadEvidence){await loadFieldEvidence(b.dataset.reloadEvidence);return;}
  if(b.dataset.preset){const dates=datePreset(b.dataset.preset);$('#q-start').value=dates.startDate;$('#q-end').value=inclusiveEnd(dates.endDate);captureDraft();return;}
  if(b.dataset.reuse){const q=state.workspace.queries.find(q=>q.id===b.dataset.reuse),m=state.workspace.metrics.find(m=>m.id===q.metric.id);if(!m)throw new Error('原指标已删除，请先在指标字典配置可用指标');const source=await api('/api/source?id='+encodeURIComponent(m.source));state.workspace.sources=state.workspace.sources.filter(s=>s.id!==source.id).concat(source);captureDraft();state.analysis={...q.definition,metricId:m.id,metricRevision:m.revision,summary:q.summary,questions:[]};state.messages=[{role:'user',content:q.request||q.name},{role:'assistant',summary:`复用历史条件，采用当前指标 v${m.revision}。请重新确认。`,content:q.summary}];state.confirmed=null;state.result=null;state.view='assistant';renderAssistant();navigate('assistant');persistDraft();return;}
  if(b.dataset.renameQuery){const q=state.workspace.queries.find(q=>q.id===b.dataset.renameQuery);const name=prompt('查询记录名称',q.name);if(name===null)return;const saved=await api('/api/queries/'+q.id,{name},'PATCH');if(state.confirmed?.id===q.id)state.confirmed=saved;await refresh();render();return;}
  if(b.dataset.deleteQuery){if(!confirm('删除这条已保存的 SQL 记录？'))return;await api('/api/queries/'+b.dataset.deleteQuery,null,'DELETE');if(state.confirmed?.id===b.dataset.deleteQuery){state.confirmed=null;state.result=null;}await refresh();render();persistDraft();return;}
  if(b.dataset.example){$('#question').value=b.dataset.example;await ask(b.dataset.example);return;}
  if(b.dataset.edit){await openMetric(b.dataset.edit);return;}
  if(b.dataset.use){const m=state.workspace.metrics.find(m=>m.id===b.dataset.use);const source=await api('/api/source?id='+encodeURIComponent(m.source));state.workspace.sources=state.workspace.sources.filter(s=>s.id!==source.id).concat(source);state.messages=[{role:'user',content:`使用指标：${m.name}`}];captureDraft();state.analysis={summary:m.description,metricId:m.id,metricRevision:m.revision,startDate:'',endDate:'',grain:'total',dimension:m.dimension,scopeFilters:[],questions:[]};state.confirmed=null;state.result=null;state.view='assistant';renderAssistant();navigate('assistant');persistDraft();return;}
  if(b.dataset.answer){const [i,j]=b.dataset.answer.split(':').map(Number);const q=state.analysis.questions[i];await ask(`${q.question}：${q.options[j]}`);return;}
  if(b.dataset.source){state.compareFields=[];state.fieldSearch='';state.source=await api('/api/source?id='+encodeURIComponent(b.dataset.source));await refresh();renderFields();return;}
  if(b.dataset.role){state.fieldRole=b.dataset.role;$('#source-detail').innerHTML=sourceDetail();return;}
  if(b.dataset.field){await openField(b.dataset.field);return;}
  if(b.dataset.query){state.confirmed=state.workspace.queries.find(q=>q.id===b.dataset.query);state.result=state.lastResults?.[b.dataset.query]||null;renderHistory();$('#saved-query').scrollIntoView({behavior:'smooth'});return;}
  if(b.dataset.copy||b.dataset.download){const q=state.workspace.queries.find(q=>q.id===(b.dataset.copy||b.dataset.download));if(b.dataset.copy){await navigator.clipboard.writeText(q.displaySql);toast('SQL 已复制');}else download(`${q.name}.sql`,`-- ${q.summary}\n-- 指标版本 ${q.metric.revision}\n${q.displaySql};\n`);return;}
  if(b.dataset.delete){if(!confirm('删除这个指标？已保存的历史 SQL 会继续保留。'))return;await api('/api/metrics/'+b.dataset.delete,null,'DELETE');$('#modal').close();await refresh();render();toast('指标已删除');return;}
  switch(b.dataset.action){
   case 'download-chart':downloadResultChart();break;
   case 'copy-result-summary':{const r=state.result,rows=resultRows(r.rows,{search:state.resultSearch||'',sort:state.resultSort||'original'});const q=state.workspace.queries.find(q=>q.id===r.id);const text=[q?.name||'查询结果',`${r.start} 至 ${inclusiveEnd(r.end)}${r.mode==='sample'?'（开始日试跑）':''}`,`当前显示 ${rows.length} / ${r.rows.length} 组${r.truncated?'；结果已截断':''}`,...rows.slice(0,10).map(row=>`${[row.period,row.dimension].filter(x=>x!==undefined).map(x=>x===null?'未填写分组':x).join(' · ')||'结果'}：${row.value===null?'无法计算':String(row.value)} ${r.unit||''}`),...(rows.length>10?['仅摘要前10组，完整数据请查看分析结果。']:[])].join('\n');await navigator.clipboard.writeText(text);toast('摘要已复制，保留原始数值和范围');break;}
   case 'apply-explanation':if(state.explanationDraft&&$('#field-form')){$('#field-form [name="label"]').value=state.explanationDraft.label;$('#field-form [name="description"]').value=state.explanationDraft.description;toast('已填入，仍需你核对后确认');}break;
   case 'compare-fields':if(!state.compareFields?.length)throw new Error('先勾选需要比较的字段，最多6个');await previewEvidence({source:state.source.id,fields:state.compareFields},'同一条记录中的字段对比');break;
   case 'preview-editor':{const form=$('#metric-form');const fields=[...new Set([form.elements.timeField.value,form.elements.valueField.value,form.elements.denominatorField.value,...new FormData(form).getAll('distinctFields')].filter(Boolean))].slice(0,6);await previewEvidence({source:state.editorSource.id,fields,scopeFilters:scopeRows($('#filters'))},'核对当前选择的原始值');break;}
   case 'field-values':await showFieldValues(b);break;
   case 'new-metric':await openMetric();break;
   case 'suggest-metric':await openMetric(null,state.analysis.suggestedMetric);break;
   case 'close-modal':$('#modal').close();break;
   case 'reset':if(state.busy){toast('正在分析，请等本次响应后再新建');break;}state.messages=[];state.analysis=null;state.analysisError='';state.confirmed=null;state.result=null;renderAssistant();break;
   case 'add-query-scope':{const m=state.workspace.metrics.find(m=>m.id===$('#q-metric').value);const source=state.workspace.sources.find(s=>s.id===m?.source);if(!source)throw new Error('请先选择指标');$('#query-scope').insertAdjacentHTML('beforeend',filterRow({},source));break;}
   case 'add-filter':$('#filters').insertAdjacentHTML('beforeend',filterRow({},state.editorSource));break;
   case 'remove-filter':b.closest('.filter-row').remove();break;
   case 'reload-tables':await loadTables();toast(`已读取 ${state.tables.length} 张表和视图`);break;
   case 'refresh-source':state.source=await api('/api/source?id='+encodeURIComponent(state.source.id)+'&refresh=true');await refresh();renderFields();toast('已同步真实字段');break;
   case 'health':await checkHealth();renderSettings();break;
   case 'test-model':{const r=await api('/api/settings/test',{});$('#model-test-result').innerHTML=`<div class="callout">连接成功 · ${h(r.model)} · ${r.latency} ms</div>`;break;}
   case 'export-visible':
   case 'export-csv':{const r=state.result,rows=b.dataset.action==='export-visible'?resultRows(r.rows,{search:state.resultSearch||'',sort:state.resultSort||'original'}):r.rows,keys=Object.keys(r.rows[0]);const csv=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';download('查询结果.csv','\uFEFF'+[keys,...rows.map(row=>keys.map(k=>row[k]))].map(row=>row.map(csv).join(',')).join('\r\n'),'text/csv');break;}
  }
 });
 captureDraft();persistDraft();
});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;await busy(e.submitter||form.querySelector('button[type=submit]')||form.querySelector('button:not([type])'),async()=>{
 if(form.id==='ask-form')await ask($('#question').value);
 if(form.id==='followup-form')await ask($('#followup').value);
 if(form.id==='metric-form')await saveMetric(form);
 if(form.id==='confirm-form')await confirmQuery(form,e.submitter?.dataset.execute==='true');
 if(form.id==='settings-form'){await api('/api/settings',{baseUrl:$('#model-url').value,model:$('#model-name').value,apiKey:$('#model-key').value},'PUT');await refresh();await checkHealth();renderSettings();toast('模型配置已保存');}
 if(form.id==='field-form'){const data=Object.fromEntries(new FormData(form));const oldLabels=state.source.columns.find(c=>c.name===data.name)?.valueLabels||{};const valueLabels=Object.assign(Object.create(null),oldLabels);form.querySelectorAll('[data-value-label]').forEach(input=>{if(input.value.trim())valueLabels[input.dataset.valueLabel]=input.value.trim();else delete valueLabels[input.dataset.valueLabel];});await api('/api/fields',{...data,valueLabels,source:state.source.id,confirmed:e.submitter?.dataset.confirmMeaning==='true',evidenceId:state.fieldEvidence||undefined},'PUT');state.source=await api('/api/source?id='+encodeURIComponent(state.source.id));await refresh();$('#modal').close();render();toast(e.submitter?.dataset.confirmMeaning==='true'?'已确认含义，业务名称将用于指标和筛选':'已保存为待确认');}
 });});
document.addEventListener('input',e=>{
 if(e.target.id==='result-search'){const pos=e.target.selectionStart;state.resultSearch=e.target.value;state.resultPage=0;$('#query-result').innerHTML=resultPanel(state.result);$('#result-search').focus();$('#result-search').setSelectionRange(pos,pos);}
 if(e.target.id==='history-search'){const pos=e.target.selectionStart;state.historySearch=e.target.value;renderHistory();$('#history-search').focus();$('#history-search').setSelectionRange(pos,pos);}
 if(e.target.id?.startsWith('field-sample-')){state.fieldEvidenceRequest=(state.fieldEvidenceRequest||0)+1;state.fieldEvidence=null;if($('#confirm-meaning'))$('#confirm-meaning').disabled=true;}
 if(e.target.id==='field-search'){const pos=e.target.selectionStart;state.fieldSearch=e.target.value;$('#source-detail').innerHTML=sourceDetail();$('#field-search').focus();$('#field-search').setSelectionRange(pos,pos);}
 if(e.target.closest('#confirm-form'))captureDraft();
 if(e.target.id==='metric-search'){const pos=e.target.selectionStart;state.metricSearch=e.target.value;renderMetrics();$('#metric-search').focus();$('#metric-search').setSelectionRange(pos,pos);}
 if(e.target.id==='source-search'){const q=e.target.value.toLowerCase();$('#source-list').innerHTML=tableButtons(state.tables.filter(t=>`${t.id} ${t.comment}`.toLowerCase().includes(q)));}
});
document.addEventListener('change',async e=>{try{
 if(['exact-values','show-chart','chart-series'].includes(e.target.id)){if(e.target.id==='exact-values')state.exactValues=e.target.checked;if(e.target.id==='show-chart')state.hideChart=!e.target.checked;if(e.target.id==='chart-series')state.chartSeries=e.target.value;$('#query-result').innerHTML=resultPanel(state.result);}
 if(e.target.id==='favorites-only'){state.favoritesOnly=e.target.checked;renderMetrics();}
 if(e.target.id==='result-sort'){state.resultSort=e.target.value;state.resultPage=0;$('#query-result').innerHTML=resultPanel(state.result);}
 if(e.target.id==='pending-only'){state.pendingOnly=e.target.checked;$('#source-detail').innerHTML=sourceDetail();}
 if(e.target.dataset.compareField){state.compareFields=state.compareFields||[];if(e.target.checked){if(state.compareFields.length>=6){e.target.checked=false;throw new Error('一次最多比较6个字段');}state.compareFields.push(e.target.dataset.compareField);}else state.compareFields=state.compareFields.filter(n=>n!==e.target.dataset.compareField);$('#source-detail').innerHTML=sourceDetail();}
 if(e.target.matches('.filter-operator')){const input=e.target.closest('.filter-row').querySelector('.filter-value');input.disabled=['is_null','not_null'].includes(e.target.value);input.placeholder=input.disabled?'此条件无需填写值':'填写或选择真实值';}
 if(e.target.matches('.filter-field')){const row=e.target.closest('.filter-row');row.querySelector('.value-candidates')?.remove();const input=row.querySelector('.filter-value');input.value='';input.dataset.selectedValues='[]';input.dataset.rawSnapshot='';}
 if(e.target.id==='aggregation')syncAggregationControls();
 if(e.target.id==='metric-status'){state.metricStatus=e.target.value;renderMetrics();}
 if(e.target.id==='metric-source'){state.editorSource=await api('/api/source?id='+encodeURIComponent(e.target.value));$('#mapping-fields').innerHTML=mappingFields({...state.editMetric,valueField:'',denominatorField:'',timeField:'',dimension:'',distinctFields:[],snapshotPolicy:'none'},state.editorSource);$('#filters').innerHTML='';syncAggregationControls();}
 if(e.target.id==='q-metric'){const m=state.workspace.metrics.find(m=>m.id===e.target.value);$('#metric-review').innerHTML=metricReview(m);if(m){state.analysis.metricRevision=m.revision;const s=await api('/api/source?id='+encodeURIComponent(m.source));if($('#q-metric')?.value!==m.id)return;state.workspace.sources=state.workspace.sources.filter(x=>x.id!==s.id).concat(s);$('#q-dimension').innerHTML=fieldOptions(s,m.dimension,'scope',true);$('#q-time').innerHTML=fieldOptions(s,m.timeField,'time');}else $('#q-dimension').innerHTML='<option value="">不分组</option>';$('#query-scope').innerHTML='';}
 
captureDraft();
}catch(e){toast(e.message);}});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-result-row]')&&e.target.tagName!=='BUTTON'&&['Enter',' '].includes(e.key)){e.preventDefault();openResultEvidence(Number(e.target.dataset.resultRow));}if(e.target.id==='question'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#ask-form').requestSubmit();}});

function datePreset(kind){const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const end=new Date(today+'T00:00:00Z');const start=new Date(end);if(kind==='month')start.setUTCDate(1);else start.setUTCDate(start.getUTCDate()-(kind==='week'?7:1));if(kind==='month')end.setUTCDate(end.getUTCDate()+1);return {startDate:start.toISOString().slice(0,10),endDate:end.toISOString().slice(0,10)};}
function persistDraft(){try{sessionStorage.setItem('marketing-draft-v1',JSON.stringify({messages:state.messages.slice(-28),analysis:state.analysis,confirmedId:state.confirmed?.id}));}catch{}}
function captureDraft(){if(state.analysis&&$('#confirm-form'))Object.assign(state.analysis,{metricId:$('#q-metric').value,startDate:$('#q-start').value,endDate:exclusiveEnd($('#q-end').value),grain:$('#q-grain').value,timeField:$('#q-time').value,dimension:$('#q-dimension').value,scopeFilters:scopeRows($('#query-scope'))});persistDraft();}
function restoreDraft(){try{const saved=JSON.parse(sessionStorage.getItem('marketing-draft-v1'));if(saved){state.messages=Array.isArray(saved.messages)?saved.messages:[];state.analysis=saved.analysis||null;state.confirmed=state.workspace.queries.find(q=>q.id===saved.confirmedId)||null;}}catch{sessionStorage.removeItem('marketing-draft-v1');}}
function selectedFilterValues(input){if(input.dataset.rawSnapshot===input.value){try{return JSON.parse(input.dataset.selectedValues||'[]');}catch{}}return input.value.split(/[,，]/).map(x=>x.trim()).filter(Boolean);}
async function showFieldValues(button){
 const row=button.closest('.filter-row'),field=row.querySelector('.filter-field').value,source=row.dataset.source;row.querySelector('.value-candidates')?.remove();
 const result=await api('/api/field-values?source='+encodeURIComponent(source)+'&field='+encodeURIComponent(field));if(!row.isConnected||row.querySelector('.filter-field').value!==field)return;
 const box=document.createElement('div');box.className='value-candidates';box.innerHTML=`<small>${h(result.note||'抽样候选，非全部取值；仍可手动输入')}</small><input class="candidate-search" aria-label="搜索候选值" placeholder="搜索候选中的名称或编号"><p class="small-text">“属于以下值”可点选多个，再点一次取消选择。</p><div class="actions candidate-options"></div><small class="candidate-empty" hidden>当前候选中未找到，可手动填写或换字段取值。</small>`;
 const update=()=>{const input=row.querySelector('.filter-value'),multi=row.querySelector('.filter-operator').value==='in';const selected=multi?selectedFilterValues(input):[input.value];box.querySelectorAll('[data-candidate]').forEach(b=>b.setAttribute('aria-pressed',String(selected.includes(b.dataset.candidate))));};
 for(const value of result.values){const b=document.createElement('button');b.type='button';b.className='btn small';b.dataset.candidate=String(value);b.textContent=result.labels?.[value]?`${result.labels[value]}（${value}）`:String(value);b.onclick=()=>{const input=row.querySelector('.filter-value');let values=[String(value)];if(row.querySelector('.filter-operator').value==='in'){values=selectedFilterValues(input);values=values.includes(String(value))?values.filter(v=>v!==String(value)):[...values,String(value)];}input.value=values.join('，');input.dataset.selectedValues=JSON.stringify(values);input.dataset.rawSnapshot=input.value;update();captureDraft();};box.querySelector('.candidate-options').append(b);}
 box.querySelector('.candidate-search').oninput=e=>{const q=e.target.value.toLowerCase();let visible=0;box.querySelectorAll('[data-candidate]').forEach(b=>{b.hidden=!b.textContent.toLowerCase().includes(q);if(!b.hidden)visible++;});box.querySelector('.candidate-empty').hidden=visible>0;};
 box.querySelector('.candidate-empty').hidden=result.values.length>0;row.append(box);update();
}
